import{_ as t,o as a,c as i,a2 as o}from"./chunks/framework.RycU2wFZ.js";const h=JSON.parse('{"title":"Good First Issues for AgentPay Contributors","description":"","frontmatter":{},"headers":[],"relativePath":"zh/contributing/good-first-issues.md","filePath":"zh/contributing/good-first-issues.md","lastUpdated":1792399623000}'),s={name:"zh/contributing/good-first-issues.md"};function n(r,e,l,d,c,p){return a(),i("div",null,[...e[0]||(e[0]=[o('<h1 id="good-first-issues-for-agentpay-contributors" tabindex="-1">Good First Issues for AgentPay Contributors <a class="header-anchor" href="#good-first-issues-for-agentpay-contributors" aria-label="Permalink to &quot;Good First Issues for AgentPay Contributors&quot;">​</a></h1><p>Welcome to AgentPay! We have compiled a list of <strong>curated, high-impact, beginner-friendly tasks</strong> designed for developers making their first contribution to the project.</p><p>Each task is scoped to be achievable within a few hours to a weekend, with clearly defined goals, relevant file pointers, and acceptance criteria.</p><hr><h2 id="🧭-how-to-pick-a-task" tabindex="-1">🧭 How to Pick a Task <a class="header-anchor" href="#🧭-how-to-pick-a-task" aria-label="Permalink to &quot;🧭 How to Pick a Task&quot;">​</a></h2><ol><li>Read through the tasks below and choose one that matches your interests (CLI tools, database queries, networking, or observability).</li><li>Check the <a href="https://github.com/open-agentpay/AgentPay/issues" target="_blank" rel="noreferrer">AgentPay Issues</a> on GitHub to ensure no one has claimed it yet.</li><li>Leave a comment on the issue saying: <em>&quot;I would like to work on this!&quot;</em> to get assigned.</li><li>Review our <a href="https://github.com/open-agentpay/AgentPay/blob/main/CONTRIBUTING.md" target="_blank" rel="noreferrer">Contributing Guide</a> for development environment setup and make sure <code>make check</code> passes locally.</li></ol><hr><h2 id="📌-issue-1-policy-config-cli-validator-agentpay-policy-validate" tabindex="-1">📌 Issue #1: Policy Config CLI Validator (<code>agentpay policy validate</code>) <a class="header-anchor" href="#📌-issue-1-policy-config-cli-validator-agentpay-policy-validate" aria-label="Permalink to &quot;📌 Issue #1: Policy Config CLI Validator (`agentpay policy validate`)&quot;">​</a></h2><ul><li><strong>Component</strong>: <code>python/packages/agentpay</code></li><li><strong>Difficulty</strong>: ⭐ Easy</li><li><strong>Tags</strong>: <code>good first issue</code>, <code>cli</code>, <code>developer-experience</code></li></ul><h3 id="background" tabindex="-1">Background <a class="header-anchor" href="#background" aria-label="Permalink to &quot;Background&quot;">​</a></h3><p>Users and CI/CD deployment pipelines configure AgentPay&#39;s financial firewall via YAML files (specifying <code>max_amount_per_tx</code>, <code>rolling_budget_24h</code>, whitelisted payees, and circuit breaker limits). Currently, if a configuration has a syntax typo or invalid Ethereum address, the error is only caught when initializing <code>SQLitePolicyEngine</code> at runtime.</p><h3 id="objective" tabindex="-1">Objective <a class="header-anchor" href="#objective" aria-label="Permalink to &quot;Objective&quot;">​</a></h3><p>Create a CLI command:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> agentpay.cli</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> policy</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> validate</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> path/to/policy.yaml</span></span></code></pre></div><p>that loads and validates the YAML against <code>PolicyConfig</code>, reporting clear human-readable errors without needing to initialize the full SQLite database.</p><h3 id="implementation-guide" tabindex="-1">Implementation Guide <a class="header-anchor" href="#implementation-guide" aria-label="Permalink to &quot;Implementation Guide&quot;">​</a></h3><ol><li><strong>File Location</strong>: <code>python/packages/agentpay/src/agentpay/cli.py</code> (create or extend).</li><li><strong>Schema</strong>: Use <code>PolicyConfig.model_validate(...)</code> (Pydantic v2).</li><li><strong>Exit Codes</strong>: <ul><li>Exit <code>0</code>: Configuration is valid. Print a clean summary table of active limits.</li><li>Exit <code>1</code>: Configuration is invalid. Print line numbers / fields and validation reasons.</li></ul></li><li><strong>Tests</strong>: Add unit tests under <code>python/tests/unit/test_cli.py</code> testing valid YAML, malformed YAML, and schema violation cases.</li></ol><hr><h2 id="📌-issue-2-sqlite-ledger-audit-exporter-agentpay-audit-export" tabindex="-1">📌 Issue #2: SQLite Ledger Audit Exporter (<code>agentpay audit export</code>) <a class="header-anchor" href="#📌-issue-2-sqlite-ledger-audit-exporter-agentpay-audit-export" aria-label="Permalink to &quot;📌 Issue #2: SQLite Ledger Audit Exporter (`agentpay audit export`)&quot;">​</a></h2><ul><li><strong>Component</strong>: <code>python/packages/agentpay</code></li><li><strong>Difficulty</strong>: ⭐ Easy</li><li><strong>Tags</strong>: <code>good first issue</code>, <code>sqlite</code>, <code>accounting</code></li></ul><h3 id="background-1" tabindex="-1">Background <a class="header-anchor" href="#background-1" aria-label="Permalink to &quot;Background&quot;">​</a></h3><p><code>SQLitePolicyEngine</code> maintains an append-only audit trail in <code>policy_ledger.db</code>, tracking every payment reservation, settlement, and failure. Developers and finance teams need a quick command to export this audit trail into structured JSON or CSV for external accounting and reconciliation.</p><h3 id="objective-1" tabindex="-1">Objective <a class="header-anchor" href="#objective-1" aria-label="Permalink to &quot;Objective&quot;">​</a></h3><p>Implement an export utility callable programmatically and via CLI:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> agentpay.cli</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> audit</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> export</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --db</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./policy_ledger.db</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --format</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> json</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --output</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> audit.json</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> agentpay.cli</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> audit</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> export</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --db</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./policy_ledger.db</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --format</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> csv</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --output</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> audit.csv</span></span></code></pre></div><h3 id="implementation-guide-1" tabindex="-1">Implementation Guide <a class="header-anchor" href="#implementation-guide-1" aria-label="Permalink to &quot;Implementation Guide&quot;">​</a></h3><ol><li><strong>Query</strong>: Select records from <code>transactions</code> and <code>reservations</code> in <code>SQLitePolicyEngine</code>.</li><li><strong>Fields to Export</strong>: <code>intent_id</code>, <code>tx_hash</code>, <code>amount</code>, <code>asset</code>, <code>payee</code>, <code>network</code>, <code>status</code>, <code>timestamp</code>, <code>created_at</code>.</li><li><strong>Masking</strong>: Ensure no private keys or internal memory references are included.</li><li><strong>Tests</strong>: Add integration tests under <code>python/tests/unit/test_audit_export.py</code> verifying that records inserted into a temporary SQLite DB export accurately in both JSON and CSV formats.</li></ol><hr><h2 id="📌-issue-3-gateway-dynamic-route-reload-on-sighup" tabindex="-1">📌 Issue #3: Gateway Dynamic Route Reload on SIGHUP <a class="header-anchor" href="#📌-issue-3-gateway-dynamic-route-reload-on-sighup" aria-label="Permalink to &quot;📌 Issue #3: Gateway Dynamic Route Reload on SIGHUP&quot;">​</a></h2><ul><li><strong>Component</strong>: <code>python/packages/agentpay-gateway</code></li><li><strong>Difficulty</strong>: ⭐⭐ Medium</li><li><strong>Tags</strong>: <code>good first issue</code>, <code>gateway</code>, <code>devops</code></li></ul><h3 id="background-2" tabindex="-1">Background <a class="header-anchor" href="#background-2" aria-label="Permalink to &quot;Background&quot;">​</a></h3><p>When deploying <code>agentpay-gateway</code> in production or staging, operators may update prices, add new API routes, or change upstream targets in <code>gateway.yaml</code>. Currently, updating routes requires restarting the gateway process, which interrupts active client connections.</p><h3 id="objective-2" tabindex="-1">Objective <a class="header-anchor" href="#objective-2" aria-label="Permalink to &quot;Objective&quot;">​</a></h3><p>On POSIX platforms (Linux / macOS), allow the gateway to reload <code>gateway.yaml</code> on receipt of a <code>SIGHUP</code> signal without terminating the running server.</p><h3 id="implementation-guide-2" tabindex="-1">Implementation Guide <a class="header-anchor" href="#implementation-guide-2" aria-label="Permalink to &quot;Implementation Guide&quot;">​</a></h3><ol><li><strong>File Location</strong>: <code>python/packages/agentpay-gateway/src/agentpay_gateway/server.py</code>.</li><li><strong>Signal Handling</strong>: Use Python&#39;s standard <code>signal.signal(signal.SIGHUP, handler)</code> or Starlette lifespan hooks.</li><li><strong>Thread Safety</strong>: Safely reload and swap the active <code>GatewayConfig.routes</code> mapping under a lock.</li><li><strong>Logging</strong>: Log at <code>INFO</code> level: <code>&quot;Reloaded gateway configuration: X active routes&quot;</code>.</li><li><strong>Tests</strong>: Add a test under <code>python/tests/integration/test_gateway_reload.py</code> verifying that modifying the YAML file and sending SIGHUP updates the routes served by the test client.</li></ol><hr><h2 id="📌-issue-4-standard-caip-2-network-registry-block-explorer-helpers" tabindex="-1">📌 Issue #4: Standard CAIP-2 Network Registry &amp; Block Explorer Helpers <a class="header-anchor" href="#📌-issue-4-standard-caip-2-network-registry-block-explorer-helpers" aria-label="Permalink to &quot;📌 Issue #4: Standard CAIP-2 Network Registry &amp; Block Explorer Helpers&quot;">​</a></h2><ul><li><strong>Component</strong>: <code>python/packages/agentpay</code></li><li><strong>Difficulty</strong>: ⭐ Easy</li><li><strong>Tags</strong>: <code>good first issue</code>, <code>web3</code>, <code>utility</code></li></ul><h3 id="background-3" tabindex="-1">Background <a class="header-anchor" href="#background-3" aria-label="Permalink to &quot;Background&quot;">​</a></h3><p>AgentPay adheres strictly to the <a href="https://github.com/ChainAgnostic/CAIPs/blob/master/CAIPs/caip-2.md" target="_blank" rel="noreferrer">CAIP-2</a> standard (e.g., <code>eip155:421614</code> for Arbitrum Sepolia). When inspecting logs or debugging payment disputes, developers frequently want to format explorer links (e.g., <code>https://sepolia.arbiscan.io/tx/0x...</code>) and human-readable network names.</p><h3 id="objective-3" tabindex="-1">Objective <a class="header-anchor" href="#objective-3" aria-label="Permalink to &quot;Objective&quot;">​</a></h3><p>Provide a clean helper module <code>agentpay.core.networks</code> with:</p><ul><li>Registry of standard Layer-2 testnets and mainnets (Arbitrum One, Arbitrum Sepolia, Base, Base Sepolia, Optimism, Polygon).</li><li>Helper function <code>get_network_name(caip2_id: str) -&gt; str</code>.</li><li>Helper function <code>get_explorer_tx_url(caip2_id: str, tx_hash: str) -&gt; str | None</code>.</li><li>Helper function <code>get_explorer_address_url(caip2_id: str, address: str) -&gt; str | None</code>.</li></ul><h3 id="implementation-guide-3" tabindex="-1">Implementation Guide <a class="header-anchor" href="#implementation-guide-3" aria-label="Permalink to &quot;Implementation Guide&quot;">​</a></h3><ol><li><strong>File Location</strong>: <code>python/packages/agentpay/src/agentpay/core/networks.py</code>.</li><li><strong>Export</strong>: Export public functions in <code>agentpay</code> top-level <code>__init__.py</code>.</li><li><strong>Tests</strong>: Add unit tests in <code>python/tests/unit/test_networks.py</code> verifying correct URL formatting and graceful handling of unknown CAIP-2 networks.</li></ol><hr><h2 id="📌-issue-5-gateway-prometheus-compatible-metrics-endpoint" tabindex="-1">📌 Issue #5: Gateway Prometheus-Compatible <code>/metrics</code> Endpoint <a class="header-anchor" href="#📌-issue-5-gateway-prometheus-compatible-metrics-endpoint" aria-label="Permalink to &quot;📌 Issue #5: Gateway Prometheus-Compatible `/metrics` Endpoint&quot;">​</a></h2><ul><li><strong>Component</strong>: <code>python/packages/agentpay-gateway</code></li><li><strong>Difficulty</strong>: ⭐⭐ Medium</li><li><strong>Tags</strong>: <code>good first issue</code>, <code>observability</code>, <code>metrics</code></li></ul><h3 id="background-4" tabindex="-1">Background <a class="header-anchor" href="#background-4" aria-label="Permalink to &quot;Background&quot;">​</a></h3><p>Platform teams running the AgentPay gateway need visibility into challenge rates, payment authorizations, and upstream response times.</p><h3 id="objective-4" tabindex="-1">Objective <a class="header-anchor" href="#objective-4" aria-label="Permalink to &quot;Objective&quot;">​</a></h3><p>Expose a <code>/metrics</code> HTTP endpoint on the gateway serving Prometheus text-based exposition metrics:</p><ul><li><code>agentpay_gateway_requests_total{route, status}</code> (Counter)</li><li><code>agentpay_gateway_challenges_issued_total{route}</code> (Counter)</li><li><code>agentpay_gateway_payments_verified_total{route}</code> (Counter)</li><li><code>agentpay_gateway_upstream_duration_seconds</code> (Histogram/Summary)</li></ul><h3 id="implementation-guide-4" tabindex="-1">Implementation Guide <a class="header-anchor" href="#implementation-guide-4" aria-label="Permalink to &quot;Implementation Guide&quot;">​</a></h3><ol><li><strong>File Location</strong>: <code>python/packages/agentpay-gateway/src/agentpay_gateway/server.py</code>.</li><li><strong>Zero Bloat</strong>: Use a lightweight in-memory metric counter class or optional integration so external dependencies remain minimal.</li><li><strong>Tests</strong>: Add integration tests verifying <code>GET /metrics</code> returns status <code>200</code> with <code>text/plain; version=0.0.4</code> and accurately increments after sample requests.</li></ol><hr><h2 id="💬-need-assistance" tabindex="-1">💬 Need Assistance? <a class="header-anchor" href="#💬-need-assistance" aria-label="Permalink to &quot;💬 Need Assistance?&quot;">​</a></h2><p>If you have any questions or get stuck while implementing a task:</p><ul><li>Join the discussion in <a href="https://github.com/open-agentpay/AgentPay/discussions" target="_blank" rel="noreferrer">GitHub Discussions</a>.</li><li>Ask in the comment thread of your assigned issue.</li><li>Maintainers are happy to help you with architecture questions, test setup, or code reviews!</li></ul>',60)])])}const u=t(s,[["render",n]]);export{h as __pageData,u as default};
